class Solution { int upperBound(vector<int>& values,int target){return upper_bound(values.begin(),values.end(),target)-values.begin();}public:int makeArrayIncreasing(vector<int>& arr1,vector<int>& arr2){sort(arr2.begin(),arr2.end());map<int,int> states{{-1,0}};for(int value:arr1){map<int,int> next;for(auto [last,operations]:states){if(value>last){if(!next.count(value))next[value]=operations;else next[value]=min(next[value],operations);}int index=upperBound(arr2,last);if(index<(int)arr2.size()){int replacement=arr2[index];if(!next.count(replacement))next[replacement]=operations+1;else next[replacement]=min(next[replacement],operations+1);}}map<int,int> pruned;int best=INT_MAX;for(auto [last,operations]:next)if(operations<best){best=operations;pruned[last]=operations;}states.swap(pruned);if(states.empty())return -1;}int answer=INT_MAX;for(auto [last,operations]:states)answer=min(answer,operations);return answer;} };
